function [xyrho,xythetab,xyn,xyopt,xynparmin,xynparmax,xynpar,xydnpar,xynperp,xyomega,xyPinc,xyfinc] = createwaveparam_dke_yp(raytracing_data,xrho_f,xrho_S,dnpar_mode,dnpar);% %	Construction of the RF input parameters for the 3D DKE equation% %	Input: %	%	    - raytracing_out: (R,Z,phi,sray,rho,rho_max,theta,kr,kz,kphi,kpar,kperp,npar,nperp,frequency,Pini,Pabs) [n,17,nray]%	    - R: Major radius %	    - Z: Vertical position%	    - phi: toroidal angle%	    - sray: raylength from launch position (m)%	    - rho: minor radius (m)%	    - rho_max: plasma minor radius (m)%	    - kr:%	    - kz:%	    - kphi:%	    - kpar:%	    - kperp:%	    - npar:%	    - nperp:%%	Output: See the comments%  %	Warning: %	  %Last Update: 05/10/03%%by J.Decker MIT/RLE <jodecker@mit.edu> and Y.Peysson CEA/DRFC <yves.peysson@cea.fr> 04/29/2003%%close all;% Temporary line for debugging phase%rho_rays = squeeze(raytracing_data(:,5,:));%Radial positions of the different rays (m)                                        rho_max = max(max(squeeze(raytracing_data(:,6,:))));%Minor plasma radius (m)    rho_rays = rho_rays/rho_max;%Normalized radial positions of the different rays%[nr_rays,n_rays] = size(rho_rays);%Number of radial positions of the rays and number of rays%nr = length(xrho_f);%Number of radial positions at which the distribution function is calculated%[grhox,grhoy] = gradient(rho_rays);%Identifying inward or outward propagationigrho = grhoy > 0;igrhom = zeros(nr_rays,n_rays);igrhom(1:nr_rays-1,:) = igrho(2:nr_rays,:);igrhom(nr_rays,:) = igrho(1,:);idgrho = igrho - igrhom;idgrho(1,:) = 1;%Launch point is considered as a point where propagation change of signidgrho(end,:) = 0;%Remove last spurious point due to the method for identifying the change of signindexray = find(idgrho);%Index where propagation change of signsidgrho = idgrho(indexray);%(-1): outward propagation, (+1) inward propagation                       %%Waveparam build-up for coupling the ray-tracing with the Fokker-Planck solver. Rays which bounce N times in the plasma %between caustics and cut-off are therefore splitted in N different sub-rays.%figuresubplot(411),plot(rho_rays),grid on, zoom onsubplot(412),plot(grhoy),grid on, zoom onsubplot(413),plot(igrho),grid on, zoom onsubplot(414),plot(idgrho),grid on, zoom on%n = 0;%i_totrays = 0;%Total sub-ray counter for i_rays = 1:n_rays,%Main ray-counter	index_subrays = [1;rem(indexray(find(nr_rays*(i_rays-1)+1 < indexray & indexray < nr_rays*i_rays)),nr_rays);nr_rays];%Index of all direction change in the propagation	for i_subrays = 1:length(index_subrays)-1,%Partial ray counter		i_totrays = i_totrays + 1;		xyrho(:,i_totrays) = xrho_f(:);%		thetab = raytracing_data(index_subrays(i_subrays):index_subrays(i_subrays+1),7,i_rays);		xythetab(:,i_totrays) = interp1(rho_rays(index_subrays(i_subrays):index_subrays(i_subrays+1),i_rays),thetab,xrho_f)';%		xyn(:,i_totrays) = n*xrho_f(:);%Resonance harmonic (0 for LH wave)		xyopt(:,i_totrays) = NaN*xrho_f(:);%		npar = raytracing_data(index_subrays(i_subrays):index_subrays(i_subrays+1),13,i_rays);  		xynpar(:,i_totrays) = interp1(rho_rays(index_subrays(i_subrays):index_subrays(i_subrays+1),i_rays),npar,xrho_f)';%        if dnpar_mode == 1,		    xydnpar(:,i_totrays) = dnpar*ones(size(xrho_f(:)));        else%            xynpar(:,i_totrays)%            [xnpar_sort,xnpar_index] = sort(xynpar(:,i_totrays)),%Sort npar values in ascending order%            xnparmin_sort = [0;(xnpar_sort(1:length(xnpar_sort)-1) + xnpar_sort(2:length(xnpar_sort)))/2],%            xnparmax_sort =  [(xnpar_sort(1:length(xnpar_sort)-1) + xnpar_sort(2:length(xnpar_sort)))/2;0],%		    xynparmin(xnpar_index,i_totrays) = xnparmin_sort(:),%		    xynparmax(xnpar_index,i_totrays) = xnparmax_sort(:),        end%				nperp = raytracing_data(index_subrays(i_subrays):index_subrays(i_subrays+1),14,i_rays);		xynperp = interp1(rho_rays(index_subrays(i_subrays):index_subrays(i_subrays+1),i_rays),nperp,xrho_f)';%		xyomega(:,i_totrays) = 2*pi*raytracing_data(1,15,i_rays)*ones(size(xrho_f(:)));%Wave frequency (Rad/s)		xyPinc(:,i_totrays) = raytracing_data(1,16,i_rays)*ones(size(xrho_f(:)));%Init power (W)%      sray = raytracing_data(index_subrays(i_subrays):index_subrays(i_subrays+1),4,i_rays);      xsray = interp1(rho_rays(index_subrays(i_subrays):index_subrays(i_subrays+1),i_rays),sray,xrho_S)';      if sidgrho(i_subrays) == -1,%Outward propagation%      	disp(['testout',',',int2str(i_rays),',',int2str(i_subrays),])      	xsray(min(find(~isnan(xsray)))-1) = raytracing_data(index_subrays(i_subrays),4,i_rays);%Core side      	if isnan(xsray(end)),%Cut-off location at r/a < 1                                                                                           		xsray(max(find(~isnan(xsray)))+1) = raytracing_data(index_subrays(i_subrays+1),4,i_rays);%Edge side      	end%			figure,plot(rho_rays(index_subrays(i_subrays):index_subrays(i_subrays+1),i_rays),sray,'g-',xrho_S,xsray,'c+')      else,%Inward propagation%      	disp(['testin',',',int2str(i_rays),',',int2str(i_subrays)])      	xsray(min(find(~isnan(xsray)))-1) = raytracing_data(index_subrays(i_subrays+1),4,i_rays);%Core side      	if isnan(xsray(end)),%Cut-off location at r/a < 1         		xsray(max(find(~isnan(xsray)))+1) = raytracing_data(index_subrays(i_subrays),4,i_rays);%Edge side      	end %         figure,plot(rho_rays(index_subrays(i_subrays):index_subrays(i_subrays+1),i_rays),sray,'b-',xrho_S,xsray,'r+')      end      xfinc = abs(diff(xsray)./diff(xrho_S'))/rho_max;		xyfinc(:,i_totrays) = xfinc(:);%%		figure,plot(rho_rays(index_subrays(i_subrays):index_subrays(i_subrays+1),i_rays),thetab,'b+-',xrho,xythetab(:,i_totrays),'r*'),zoom on,grid on;% Temporary line for debugging phase%		figure,plot(rho_rays(index_subrays(i_subrays):index_subrays(i_subrays+1),i_rays),npar,'b+-',xrho_f,xynpar(:,i_totrays),'r*'),zoom on,grid on;% Temporary line for debugging phase%		figure,plot(rho_rays(index_subrays(i_subrays):index_subrays(i_subrays+1),i_rays),nperp,'b+-',xrho,xynperp(:,i_totrays),'r*'),zoom on,grid on;% Temporary line for debugging phase%	endenddisp(i_totrays)%